<script setup lang="ts">
import { invoke } from "@tauri-apps/api/core";
import { onMounted, ref } from "vue";
import { BarChart3, Download, RefreshCw } from "lucide-vue-next";
interface Summary { active_products: number; variant_count: number; total_stock: number; sales_today: number; revenue_today: number; profit_today: number; low_stock_count: number }
const today = new Date().toISOString().slice(0, 10); const periodStart = ref(`${today.slice(0, 8)}01`); const periodEnd = ref(today); const summary = ref<Summary | null>(null); const error = ref(""); const loading = ref(true); const money = (value: number) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(value);
async function load() { loading.value = true; error.value = ""; try { summary.value = await invoke<Summary>("report_summary_range", { request: { period_start: periodStart.value, period_end: periodEnd.value } }); } catch (e) { error.value = String(e); } finally { loading.value = false; } }
function exportCsv() { if (!summary.value) return; const rows = [["Metrik", "Nilai"], ["Periode", `${periodStart.value} - ${periodEnd.value}`], ["Produk aktif", summary.value.active_products], ["Total varian", summary.value.variant_count], ["Total stok", summary.value.total_stock], ["Penjualan", summary.value.sales_today], ["Pendapatan", summary.value.revenue_today], ["Laba", summary.value.profit_today], ["Stok menipis", summary.value.low_stock_count]]; const csv = rows.map((row) => row.map((value) => `"${String(value).replace(/"/g, '""')}"`).join(",")).join("\r\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = `siambruk-report-${periodStart.value}-${periodEnd.value}.csv`; link.click(); URL.revokeObjectURL(url); }
onMounted(load);
</script>

<template><section class="module-page"><div class="section-intro"><div><p class="eyebrow">Analisis</p><h2>Laporan ringkas</h2><p class="intro-copy">Pilih periode untuk menghitung penjualan, pendapatan, dan laba dari transaksi tersimpan.</p></div><div class="action-row"><button class="secondary-button" type="button" @click="load"><RefreshCw :size="15" /> Segarkan</button><button class="secondary-button" :disabled="!summary" type="button" @click="exportCsv"><Download :size="15" /> CSV</button></div></div><section class="panel evaluation-controls"><div><p class="eyebrow">Periode laporan</p><div class="form-row"><label>Mulai<input v-model="periodStart" type="date" /></label><label>Selesai<input v-model="periodEnd" type="date" /></label></div></div><button class="primary-button" type="button" @click="load">Hitung laporan</button></section><p v-if="error" class="form-error">{{ error }}</p><section class="metric-grid report-metrics"><article class="metric-card"><span class="metric-label">Produk aktif</span><strong class="metric-value">{{ summary?.active_products ?? "—" }}</strong></article><article class="metric-card"><span class="metric-label">Total stok</span><strong class="metric-value">{{ summary?.total_stock ?? "—" }}</strong></article><article class="metric-card"><span class="metric-label">Penjualan periode</span><strong class="metric-value">{{ summary?.sales_today ?? "—" }}</strong></article><article class="metric-card"><span class="metric-label">Pendapatan periode</span><strong class="metric-value report-money">{{ summary ? money(summary.revenue_today) : "—" }}</strong></article></section><section class="panel report-panel"><div class="panel-heading"><div><p class="eyebrow">Kesehatan operasional</p><h3>Ringkasan periode</h3></div><BarChart3 :size="18" class="panel-icon" /></div><div v-if="loading" class="table-state">Menghitung ringkasan...</div><div v-else class="report-list"><div><span>Laba tercatat</span><strong>{{ money(summary?.profit_today ?? 0) }}</strong></div><div><span>Varian stok menipis</span><strong>{{ summary?.low_stock_count ?? 0 }}</strong></div><div><span>Total varian</span><strong>{{ summary?.variant_count ?? 0 }}</strong></div></div></section></section></template>
